require_role('buyer');$bid=user()['buyer_id'];$s=db()->prepare('SELECT COUNT(*) total,SUM(status="pending") pending,SUM(status="delivered") delivered,COALESCE(SUM(total),0) spent FROM orders WHERE buyer_id=?');$s->execute([$bid]);$stats=$s->fetch();$s=db()->prepare('SELECT * FROM orders WHERE buyer_id=? ORDER BY created_at DESC LIMIT 5');$s->execute([$bid]);$orders=$s->fetchAll();$recommended=db()->query("SELECT p.*,c.name category_name,u.name farmer_name,f.verification_status,(SELECT COALESCE(AVG(rating),0) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') rating,(SELECT COUNT(*) FROM reviews r WHERE r.product_id=p.id AND r.status='visible') review_count FROM products p JOIN categories c ON c.id=p.category_id JOIN farmers f ON f.id=p.farmer_id JOIN users u ON u.id=f.user_id WHERE p.status='active' ORDER BY p.sales_count DESC LIMIT 4")->fetchAll();$chartData=['pending'=>0,'confirmed'=>0,'preparing'=>0,'ready'=>0,'shipping'=>0,'delivered'=>0,'cancelled'=>0];$chartQuery=$s=db()->prepare('SELECT status,COUNT(*) total FROM orders WHERE buyer_id=? GROUP BY status');$chartQuery->execute([$bid]);foreach($chartQuery->fetchAll() as $row){if(array_key_exists($row['status'],$chartData))$chartData[$row['status']]=(int)$row['total'];}include __DIR__.'/../includes/header.php';?><div class="dashboard-layout"><?php include __DIR__.'/../includes/sidebar.php';?><section class="dashboard-content"><div class="dashboard-top"><div><span class="eyebrow">A sua atividade</span><h1>Olá, <?=e(explode(' ',user()['name'])[0])?>.</h1><p class="text-muted">Aqui está o resumo das suas compras.</p></div><a class="btn btn-primary" href="<?=base_path('marketplace.php')?>">Explorar marketplace</a></div><div class="row g-3 mb-4"><?php foreach([['Pedidos realizados',$stats['total']??0,'bi-receipt','primary'],['Pendentes',$stats['pending']??0,'bi-clock','warning'],['Concluídos',$stats['delivered']??0,'bi-check-circle','success'],['Total gasto',money($stats['spent']??0),'bi-wallet2','info']] as $m):?><div class="col-sm-6 col-xl-3"><div class="stat-card"><span class="stat-icon <?=$m[3]?>"><i class="bi <?=$m[2]?>"></i></span><div><small><?=$m[0]?></small><strong><?=$m[1]?></strong></div></div></div><?php endforeach;?></div><div class="content-card mb-4"><div class="card-heading"><h4>Últimos pedidos</h4><a href="<?=base_path('comprador/pedidos.php')?>">Ver todos</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Data</th><th>Total</th><th>Estado</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?=e($o['order_number'])?></strong></td><td><?=date('d/m/Y',strtotime($o['created_at']))?></td><td><?=money($o['total'])?></td><td><?=order_status_badge($o['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="content-card mb-4"><div class="card-heading"><h4>Distribuição dos pedidos</h4><span class="small text-muted">Estado atual</span></div><div class="row align-items-center"><div class="col-md-5"><canvas id="buyerOrdersChart" height="190"></canvas></div><div class="col-md-7"><p class="small text-muted mb-2">Acompanhe a evolução da sua atividade de compra.</p><?php foreach($chartData as $status=>$total): ?><div class="d-flex justify-content-between border-bottom py-2 small"><span><?=e(order_status_label($status))?></span><strong><?=safe_int($total)?></strong></div><?php endforeach; ?></div></div><script>document.addEventListener('DOMContentLoaded',()=>new Chart(document.getElementById('buyerOrdersChart'),{type:'doughnut',data:{labels:<?=json_encode(array_map('order_status_label',array_keys($chartData)),JSON_UNESCAPED_UNICODE)?>,datasets:[{data:<?=json_encode(array_values($chartData),JSON_NUMERIC_CHECK)?>,backgroundColor:['#e3a93c','#4d95aa','#1c7c54','#77a96b','#667f9e','#2a9d70','#c4554a'],borderWidth:0}]},options:{plugins:{legend:{position:'bottom'}},cutout:'68%'}}));</script></div><h3 class="mb-3">Pode gostar destes produtos</h3><div class="row g-4"><?php foreach($recommended as $p):?><div class="col-sm-6 col-lg-3"><?php include __DIR__.'/../includes/product-card.php';?></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php';?>
